/**
 * Highest production-compile gate requested for the current project snapshot.
 *
 * @evidence contracts/common.md#principled-implementation The four scopes form progressively stricter admission: tracked design, deterministic source and generated bytes, current review completion, then final renderer-owned deliverables and parsed media identity.
 * @evidence contracts/common.md#clear-and-simple-design One closed scope chooses the highest required gate rather than exposing independent booleans that could request final delivery without source or review admission.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Scope does not invent a current compile or accepted review; each stricter gate depends on the current upstream inputs rather than reusing stale success.
 * @evidence contracts/common.md#meaningful-documentation Explains every scope's added responsibility, including sandboxed TypeScript, generated-artifact materialization, exact current review and final byte receipts.
 * @author Samchon
 */
export interface IAutoMovieBuildProjectInput {
  /**
   * Highest atomic gate to enforce. `design` validates the tracked graph only; `source` additionally compiles sandboxed TypeScript and materializes owned generated artifacts; `review` additionally requires every current review target complete; `final` additionally verifies required renderer-owned deliverables, byte receipts and parsed media facts.
   */
  scope: "design" | "source" | "review" | "final";
}
